using System;using System.Collections.Generic;using System.IO;using System.Text;using System.Security.AccessControl;using System.Security.Principal;using Enclave.OwnedRpc;
public static class NativeRpcStartLauncherHarness {
 static int count;static void Check(bool x){if(!x)throw new Exception("Assertion");}static void Refuse(Action f){bool failed=false;try{f();}catch{failed=true;}Check(failed);}static void Test(string name,Action f){f();count++;Console.WriteLine("PASS "+name);}static string H(char c){return new string(c,64);}static byte[] B(string s){return Encoding.UTF8.GetBytes(s);}
 static Dictionary<string,object> D(params object[] x){var d=new Dictionary<string,object>();for(int i=0;i<x.Length;i+=2)d.Add((string)x[i],x[i+1]);return d;}
 sealed class Case:IDisposable {
  internal readonly string Root,Home,Workers,Config=H('a');internal readonly long Now=BoundedWorker.MonotonicMilliseconds();internal readonly byte[] Worker=B("inert pinned worker fixture"),Keeper=B("inert pinned keeper fixture");internal readonly NativeRpcManagerLedger Ledger;internal readonly NativeRpcDefinitionPlan Plan;internal readonly string Original;
  internal Case(){Home=Path.Combine(Path.GetPathRoot(Environment.SystemDirectory),"rpc-start-launch-"+Guid.NewGuid().ToString("N"));var acl=new DirectorySecurity();acl.SetOwner(new SecurityIdentifier("S-1-5-32-544"));acl.SetAccessRuleProtection(true,false);foreach(string sid in new[]{"S-1-5-18","S-1-5-32-544"})acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.CreateDirectory(Home,acl);Root=Path.Combine(Home,"ledger");Directory.CreateDirectory(Root,acl);Workers=Path.Combine(Home,"workers");Directory.CreateDirectory(Workers,acl);
   var security=new FileSecurity();security.SetOwner(new SecurityIdentifier("S-1-5-32-544"));security.SetAccessRuleProtection(true,false);foreach(string sid in new[]{"S-1-5-18","S-1-5-32-544"})security.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid),FileSystemRights.FullControl,AccessControlType.Allow));using(var f=new FileStream(Path.Combine(Root,"manager.lock"),FileMode.CreateNew,FileSystemRights.WriteData,FileShare.None,4096,FileOptions.WriteThrough,security))f.Flush(true);
   Ledger=new NativeRpcManagerLedger(Root,Config,Current);Ledger.Files.NewDirectory(Path.Combine(Root,"transport"));var a=Ledger.Begin(new string('b',32),"rpc"+new string('c',32),"0x"+H('d'),Now);Original=ProtectedAttempt.Hash(NativeRpcManagerLedger.Encode(a));string attempt=(string)a["attempt"];
   Plan=new NativeRpcDefinitionPlan(attempt,(string)a["boot"],(string)a["managerEpoch"],(string)a["instance"],(string)a["deployment"],H('e'),H('f'),H('a'),H('b'),H('c'),H('d'),Path.Combine(Home,attempt),Now,Now+900000,H('e'),H('f'),ProtectedAttempt.Hash(Worker));
   Ledger.Files.NewDirectory(Plan.Root);Ledger.Files.Publish(Path.Combine(Plan.Root,"native-definition-plan.txt"),B(Plan.Encode()));
  }
  internal void Current(){if(BoundedWorker.MonotonicMilliseconds()-Now>=15000)throw new Exception("Fixture deadline");}
  internal NativeStartContract Contract(string role,long now){return new NativeStartContract(Ledger.Files,Plan,Workers,role=="start"?Worker:Keeper,Worker,role,now,now+25000);}
  public void Dispose(){Ledger.Dispose();}
 }
 public static int Main(){try{BoundedWorker.EnterSupervisorEnvelope(256UL*1024*1024);
  Test("prepared keeper pair binds distinct immutable contracts to original end plus thirty",()=>{using(var c=new Case()){long n=BoundedWorker.MonotonicMilliseconds();var a=c.Contract("watch",n);var b=c.Contract("watch-backup",n);Check(a.Root!=b.Root&&a.Hash!=b.Hash&&a.End==c.Plan.Deadline+30000&&b.End==a.End);using(var first=ProtectedAttempt.PinNativeLifecycleController(a.Path,a.Hash))using(var second=ProtectedAttempt.PinNativeLifecycleController(b.Path,b.Hash)){Check(first.Operation=="watch"&&second.Operation=="watch-backup");Check(first.PermitHash==c.Plan.Digest&&second.PermitHash==c.Plan.Digest);Check(File.ReadAllBytes(Path.Combine(a.Root,"worker.exe")).Length==c.Worker.Length);}}});
  Test("prepared start lease and original journal keep original plan and short worker endpoint",()=>{using(var c=new Case()){long n=BoundedWorker.MonotonicMilliseconds();var a=c.Contract("start",n);using(var lease=ProtectedAttempt.PinNativeStartController(a.Path,a.Hash))using(var pin=ProtectedAttempt.PinNativeStartJournalController(lease.PermitPath,lease.PermitHash,lease)){Check(a.End==n+20000&&pin.NativeDefinitionPlan.Encode()==c.Plan.Encode());Check(!File.Exists(Path.Combine(a.Root,"admit")));Check(!File.Exists(Path.Combine(a.Root,"worker.exe")));}}});
  Test("expiry rollback and unsupported role cannot create a new worker namespace",()=>{using(var c=new Case()){int before=Directory.GetDirectories(c.Workers).Length;Refuse(()=>c.Contract("watch",c.Plan.Origin-1));Refuse(()=>c.Contract("start",c.Plan.Deadline));Refuse(()=>c.Contract("adopt",c.Now));Check(Directory.GetDirectories(c.Workers).Length==before);}});
  Test("worker image mismatch refuses before any task or directory",()=>{using(var c=new Case()){int before=Directory.GetDirectories(c.Workers).Length;Refuse(()=>new NativeStartContract(c.Ledger.Files,c.Plan,c.Workers,c.Keeper,c.Worker,"start",c.Now,c.Now+25000));Refuse(()=>new NativeStartContract(c.Ledger.Files,c.Plan,c.Workers,c.Keeper,c.Keeper,"watch",c.Now,c.Now+25000));Check(Directory.GetDirectories(c.Workers).Length==before);}});
  Test("start request consumed before preparation survives reconstruction and refuses replay",()=>{string root,original;NativeRpcDefinitionPlan plan;using(var c=new Case()){root=c.Root;original=c.Original;plan=c.Plan;NativeStartLaunchRecords.Consume(c.Ledger,original,plan,B("definition receipt"));Check(File.Exists(Path.Combine(root,"start-request.json")));Check(!File.Exists(Path.Combine(root,"start-dispatch.json")));}using(var ledger=new NativeRpcManagerLedger(root,H('a'),()=>{})){Check((string)ledger.Inspect()["state"]=="held");Refuse(()=>NativeStartLaunchRecords.Consume(ledger,original,plan,B("definition receipt")));}});
  Test("foreign original request cannot consume start authority",()=>{using(var c=new Case()){Refuse(()=>NativeStartLaunchRecords.Consume(c.Ledger,H('f'),c.Plan,B("definition")));Check(!File.Exists(Path.Combine(c.Root,"start-request.json")));}});
  Test("torn start request stays held across inspect and original read",()=>{using(var c=new Case()){c.Ledger.Files.Publish(Path.Combine(c.Root,"start-request.json.pending"),B("partial"));Refuse(()=>c.Ledger.Inspect());Refuse(()=>c.Ledger.Original(c.Original));Refuse(()=>NativeStartLaunchRecords.Consume(c.Ledger,c.Original,c.Plan,B("definition")));}});
  Test("historical running result never grants serving fencing or release",()=>{using(var c=new Case()){var d=D("schema","native-rpc-start-worker-result/1","plan",c.Plan.Digest,"receipt",H('e'),"state","native-running-observed","rpcReady",false,"providerOperationFenced",false,"reservationMayRelease",false);Check((string)NativeStartLaunchRecords.Result(c.Plan,StartRecords.Encode(d),H('e'))["state"]=="native-running-observed");foreach(string flag in new[]{"rpcReady","providerOperationFenced","reservationMayRelease"}){d[flag]=true;Refuse(()=>NativeStartLaunchRecords.Result(c.Plan,StartRecords.Encode(d),H('e')));d[flag]=false;}d["plan"]=H('f');Refuse(()=>NativeStartLaunchRecords.Result(c.Plan,StartRecords.Encode(d),H('e')));}});
  Test("short remaining original time refuses without deadline extension",()=>{using(var c=new Case()){long near=c.Plan.Deadline-4999;Refuse(()=>c.Contract("start",near));Refuse(()=>new NativeStartContract(c.Ledger.Files,c.Plan,c.Workers,c.Worker,c.Worker,"start",c.Now,c.Now+4999));}});
  Test("both v1 definition-only and explicit v2 pins validate without default upgrade",()=>{using(var c=new Case()){var d=D("schema","native-rpc-manager-controller/1","ledgerRoot",c.Root,"attemptsRoot",c.Root+"-attempts","workersRoot",c.Root+"-workers","runtimeId",H('a'),"profileSha256",H('b'),"admissionSha256",H('c'),"firmwareSha256",H('d'),"initialStateSha256",H('e'),"workerSha256",H('f'),"admissionPath",Path.Combine(c.Root,"admission"),"firmwarePath",Path.Combine(c.Root,"firmware"),"initialStatePath",Path.Combine(c.Root,"state"),"profilePath",Path.Combine(c.Root,"profile"),"workerPath",Path.Combine(c.Root,"worker"));NativeRpcControllerEntry.ValidateConfiguration(d);d["schema"]="native-rpc-manager-controller/2";Refuse(()=>NativeRpcControllerEntry.ValidateConfiguration(d));d.Add("keeperPath",Path.Combine(c.Root,"keeper"));d.Add("keeperSha256",H('a'));d.Add("startControllerPath",Path.Combine(c.Root,"start"));d.Add("startControllerSha256",H('b'));NativeRpcControllerEntry.ValidateConfiguration(d);d["keeperSha256"]=new string('0',64);Refuse(()=>NativeRpcControllerEntry.ValidateConfiguration(d));}});
  Console.WriteLine("TOTAL "+count+" PASS; actual administrator files/contracts; no SYSTEM scheduling, admission or provider execution");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
